/* Generated from ghibli-studio.astrale-theme.json. Consumer-owned after installation. */
:root,
[data-ui-preset='ghibli-studio'],
[data-ui-theme='ghibli-studio'] {
  color-scheme: light;
  --ui-background: oklch(0.91 0.05 82.69);
  --ui-foreground: oklch(0.41 0.08 79.04);
  --ui-card: oklch(0.92 0.04 83.86);
  --ui-card-foreground: oklch(0.41 0.08 73.75);
  --ui-popover: oklch(0.92 0.04 83.86);
  --ui-popover-foreground: oklch(0.41 0.08 73.75);
  --ui-primary: oklch(0.71 0.10 111.99);
  --ui-primary-foreground: oklch(0.98 0.01 3.71);
  --ui-secondary: oklch(0.88 0.05 83.41);
  --ui-secondary-foreground: oklch(0.51 0.08 79.21);
  --ui-muted: oklch(0.86 0.06 83.48);
  --ui-muted-foreground: oklch(0.51 0.08 74.26);
  --ui-accent: oklch(0.86 0.05 84.50);
  --ui-accent-foreground: oklch(0.26 0.02 358.42);
  --ui-destructive: oklch(0.63 0.24 29.21);
  --ui-destructive-foreground: oklch(0.98 0.01 3.71);
  --ui-border: oklch(0.74 0.06 79.81);
  --ui-input: oklch(0.74 0.06 79.81);
  --ui-ring: oklch(0.51 0.08 74.26);
  --ui-chart-1: oklch(0.66 0.19 41.68);
  --ui-chart-2: oklch(0.70 0.12 183.20);
  --ui-chart-3: oklch(0.48 0.08 211.46);
  --ui-chart-4: oklch(0.84 0.17 85.07);
  --ui-chart-5: oklch(0.74 0.17 60.21);
  --ui-sidebar: oklch(0.87 0.06 83.96);
  --ui-sidebar-foreground: oklch(0.41 0.08 79.04);
  --ui-sidebar-primary: oklch(0.26 0.02 358.42);
  --ui-sidebar-primary-foreground: oklch(0.98 0.01 3.71);
  --ui-sidebar-accent: oklch(0.83 0.06 84.46);
  --ui-sidebar-accent-foreground: oklch(0.26 0.02 358.42);
  --ui-sidebar-border: oklch(0.91 0.00 0.43);
  --ui-sidebar-ring: oklch(0.71 0.00 0.37);
  --ui-radius: 0.625rem;
  --ui-radius-panel: 0.625rem;
  --ui-control-height: 2.25rem;
  --ui-control-height-sm: 2rem;
  --ui-control-height-lg: 2.5rem;
  --ui-font-body: 'PT Serif', ui-serif, serif;
  --ui-font-heading: 'Nunito', ui-sans-serif, sans-serif;
  --ui-font-mono: 'JetBrains Mono', ui-monospace, monospace;
  --ui-shadow-control: 0 1px 3px 0px oklch(0.00 0 0 / 0.05);
  --ui-shadow-panel:
    0 1px 3px 0px oklch(0.00 0 0 / 0.10), 0 4px 6px -1px oklch(0.00 0 0 / 0.10);
  --ui-motion-fast: 120ms;
  --ui-motion-standard: 180ms;
}

:root.dark,
[data-ui-preset='ghibli-studio'].dark,
[data-ui-theme='ghibli-studio'].dark {
  color-scheme: dark;
  --ui-background: oklch(0.20 0.01 48.35);
  --ui-foreground: oklch(0.88 0.05 79.26);
  --ui-card: oklch(0.25 0.01 56.14);
  --ui-card-foreground: oklch(0.88 0.05 79.26);
  --ui-popover: oklch(0.25 0.01 56.14);
  --ui-popover-foreground: oklch(0.88 0.05 79.26);
  --ui-primary: oklch(0.64 0.05 115.39);
  --ui-primary-foreground: oklch(0.98 0.01 3.71);
  --ui-secondary: oklch(0.33 0.02 60.70);
  --ui-secondary-foreground: oklch(0.88 0.05 83.41);
  --ui-muted: oklch(0.27 0.01 39.35);
  --ui-muted-foreground: oklch(0.74 0.06 79.81);
  --ui-accent: oklch(0.33 0.02 60.70);
  --ui-accent-foreground: oklch(0.86 0.05 84.50);
  --ui-destructive: oklch(0.63 0.24 29.21);
  --ui-destructive-foreground: oklch(0.98 0.01 3.71);
  --ui-border: oklch(0.33 0.02 60.70);
  --ui-input: oklch(0.33 0.02 60.70);
  --ui-ring: oklch(0.64 0.05 115.39);
  --ui-chart-1: oklch(0.66 0.19 41.68);
  --ui-chart-2: oklch(0.70 0.12 183.20);
  --ui-chart-3: oklch(0.48 0.08 211.46);
  --ui-chart-4: oklch(0.84 0.17 85.07);
  --ui-chart-5: oklch(0.74 0.17 60.21);
  --ui-sidebar: oklch(0.23 0.01 56.09);
  --ui-sidebar-foreground: oklch(0.88 0.05 79.26);
  --ui-sidebar-primary: oklch(0.64 0.05 115.39);
  --ui-sidebar-primary-foreground: oklch(0.98 0.01 3.71);
  --ui-sidebar-accent: oklch(0.33 0.02 60.70);
  --ui-sidebar-accent-foreground: oklch(0.86 0.05 84.50);
  --ui-sidebar-border: oklch(0.33 0.02 60.70);
  --ui-sidebar-ring: oklch(0.64 0.05 115.39);
  --ui-radius: 0.625rem;
  --ui-radius-panel: 0.625rem;
  --ui-control-height: 2.25rem;
  --ui-control-height-sm: 2rem;
  --ui-control-height-lg: 2.5rem;
  --ui-font-body: 'PT Serif', ui-serif, serif;
  --ui-font-heading: 'Nunito', ui-sans-serif, sans-serif;
  --ui-font-mono: 'JetBrains Mono', ui-monospace, monospace;
  --ui-shadow-control: 0 1px 3px 0px oklch(0.00 0 0 / 0.05);
  --ui-shadow-panel:
    0 1px 3px 0px oklch(0.00 0 0 / 0.10), 0 4px 6px -1px oklch(0.00 0 0 / 0.10);
  --ui-motion-fast: 120ms;
  --ui-motion-standard: 180ms;
}
